createPartObj(partNum, headers, parent) {
  let ct;

  if (headers.has("content-type")) {
    ct = headers.contentType.type;
    const it = headers.get("content-type").entries();
    for (const i of it) {
      ct += "; " + i[0] + '="' + i[1] + '"';
    }
  }

  return {
    partNum,
    headers,
    fullContentType: ct,
    body: "",
    size: 0,
    parent,
    subParts: [],
  };
}

